Method.Implementation:
#Dim tResultSet As %SQL.StatementResult

Set tStatus = $$$OK
Try {
	
	// Clean out the report data table
	Set tStatus = ..ClearExistingData()
	$$$ThrowOnError(tStatus)
	
	// Extract and load ens production setting data into DB tables
	Set tStatus = ..ExtractData(pBeginDateTime,pEndDateTime,pEventSource,pEventType,pEventName,pUsername,pDescriptionKey,pEventDataKey)
	$$$ThrowOnError(tStatus)
	
	// Write out to report file
	Set tStatus = ..WriteReport(pDelimiter)
	$$$ThrowOnError(tStatus)
	
} Catch eException {
	Set tStatus = eException.AsStatus()
}
Quit tStatus

Set tStatus = $$$OK
Try {
	// Clear existing report data
	Set SQLCODE = ""
	&sql(DELETE FROM IHC_EAI_Report_AuditLog.Data)
	If ((SQLCODE '= 0) && (SQLCODE '= 100)) {
		$$$ThrowStatus($$$ERROR($$$GeneralError, "Failed to clear report data."))	
	}
	
} Catch eException {
	Set tStatus = eException.AsStatus()
}
Quit tStatus

#Dim tResultSet As %SQL.StatementResult
Set tStatus = $$$OK Try {
Set tQuery = "SELECT AuditLogId,EventSource,EventType,EventName,EventData,Namespace,Username,Description,Pid,LocalTimeStamp " _ "FROM IHC_EAI_Report_AuditLog.Data " _ "ORDER BY LocalTimeStamp ASC"
Set tStatement = ##class(%SQL.Statement).%New() Set tStatus = tStatement.%Prepare(tQuery) $$$ThrowOnError(tStatus) Set tResultSet = tStatement.%Execute()
While (tResultSet.%Next(.tStatus)) { $$$ThrowOnError(tStatus)
Set tAuditLogId = tResultSet.%GetData(1) Set tEventSource = tResultSet.%GetData(2) Set tEventType = tResultSet.%GetData(3) Set tEventName = tResultSet.%GetData(4) Set tEventData = tResultSet.%GetData(5) Set tNamespace = tResultSet.%GetData(6) Set tUsername = tResultSet.%GetData(7) Set tDescription = tResultSet.%GetData(8) Set tPid = tResultSet.%GetData(9) Set tLocalTimeStamp = tResultSet.%GetData(10)
Set tLine = tLocalTimeStamp _ pDelimiter _ tEventSource _ pDelimiter _ tEventType _ pDelimiter _ tEventName _ pDelimiter _ tNamespace _ pDelimiter _ tDescription _ pDelimiter _ tUsername _ pDelimiter _ $ZSTRIP(tEventData,"*C") _ pDelimiter _ tPid
Do ..Report(.tReportFile,tLine) $$$ThrowOnError(tStatus) } $$$ThrowOnError(tStatus)
// Close the report Do ..Report(.tReportFile,"",1) $$$ThrowOnError(tStatus)
} Catch eException { Set tStatus = eException.AsStatus() } Quit tStatus
